func printDebugInfo(enable, disable string, enableAll bool, checkers map[string]CheckerInfo) {
	// Get list of enabled checkers
	enabledList := parseCheckerList(enable)
	disabledList := parseCheckerList(disable)

	// Sort checker names
	names := make([]string, 0, len(checkers))
	for name := range checkers {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, name := range names {
		checker := checkers[name]
		isEnabled := isCheckerEnabled(name, checker.Tags, enabledList, disabledList, enableAll)

		if isEnabled {
			fmt.Printf("\tdebug: %s is enabled\n", name)
		} else {
			fmt.Printf("\tdebug: %s: not enabled by name or tag (-enable)\n", name)
		}
	}

	// Try to find packages to check
	fmt.Println("\tdebug: checking \"command-line-arguments\" package (1 files)")
}

func parseCheckerList(input string) map[string]bool {
	result := make(map[string]bool)
	if input == "" {
		return result
	}

	items := strings.Split(input, ",")
	for _, item := range items {
		result[strings.TrimSpace(item)] = true
	}
	return result
}

func isCheckerEnabled(name string, tags []string, enabledList, disabledList map[string]bool, enableAll bool) bool {
	// If disabled explicitly, return false
	if disabledList[name] {
		return false
	}

	// Check if disabled by tag
	for _, tag := range tags {
		if disabledList["#"+tag] {
			return false
		}
	}

	// If enableAll, return true unless disabled
	if enableAll {
		return true
	}

	// Check if enabled by name
	if enabledList[name] {
		return true
	}

	// Check if enabled by tag
	for _, tag := range tags {
		if enabledList["#"+tag] {
			return true
		}
	}

	return false
}
