func main() {
	if len(os.Args) < 2 {
		fmt.Println("no args provided")
		return
	}

	command := os.Args[1]

	switch command {
	case "help":
		showHelp()
	case "version":
		showVersion()
	case "doc":
		handleDoc(os.Args[2:])
	case "check":
		handleCheck(os.Args[2:])
	default:
		fmt.Printf("\"%s\" unknown command\n", command)
		fmt.Println("Run \"go-critic help\" for usage.")
		fmt.Printf("\nno such command \"%s\"\n", command)
	}
}

func showHelp() {
	fmt.Println("Usage:")
	fmt.Println("")
	fmt.Println("    go-critic <command> [arguments...]")
	fmt.Println("")
	fmt.Println("The commands are:")
	fmt.Println("")
	fmt.Println("    check             run linter over specified targets")
	fmt.Println("    doc               get installed checkers documentation")
	fmt.Println("    help              shows help message")
	fmt.Println("    version           shows version of the application")
	fmt.Println("")
	fmt.Printf("Version: %s\n\n", Version)
}

func showVersion() {
	fmt.Printf("go-critic version: %s\n\n", Version)
}

func handleDoc(args []string) {
	if len(args) == 0 {
		// List all checkers
		listCheckers()
	} else {
		// Show specific checker doc
		showCheckerDoc(args[0])
	}
}

func listCheckers() {
	// Sort checker names
	names := make([]string, 0, len(checkers))
	for name := range checkers {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, name := range names {
		checker := checkers[name]
		tagsStr := fmt.Sprintf("[%s]", strings.Join(checker.Tags, " "))
		fmt.Printf("%s %s\n", name, tagsStr)
	}
}

func showCheckerDoc(name string) {
	checker, exists := checkers[name]
	if !exists {
		fmt.Printf("checker %s not found\n", name)
		return
	}

	fmt.Printf("%s checker documentation\n", name)
	fmt.Println("URL: https://github.com/go-critic/go-critic/checkers")
	fmt.Printf("Tags: [%s]\n", strings.Join(checker.Tags, " "))
	fmt.Println("")
	fmt.Println(checker.Description)
	fmt.Println("")

	if checker.NonCompliant != "" {
		fmt.Println("Non-compliant code:")
		fmt.Println(checker.NonCompliant)
		fmt.Println("")
	}

	if checker.Compliant != "" {
		fmt.Println("Compliant code:")
		fmt.Println(checker.Compliant)
		fmt.Println("")
	}

	if len(checker.Params) > 0 {
		fmt.Println("Checker parameters:")
		// Sort parameter names
		paramNames := make([]string, 0, len(checker.Params))
		for paramName := range checker.Params {
			paramNames = append(paramNames, paramName)
		}
		sort.Strings(paramNames)

		for _, paramName := range paramNames {
			param := checker.Params[paramName]
			fmt.Printf("  -@%s.%s %s\n", name, paramName, param.Type)
			fmt.Printf("    \t%s (default %s)\n", param.Description, param.Default)
		}
	}
}

func handleCheck(args []string) {
	// Parse flags for check command
	checkCmd := flag.NewFlagSet("check", flag.ContinueOnError)

	// Define all the flags
	enable := checkCmd.String("enable", "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc", "comma-separated list of enabled checkers. Can include #tags")
	disable := checkCmd.String("disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
	enableAll := checkCmd.Bool("enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
	verbose := checkCmd.Bool("v", false, "whether to print output useful during linter debugging")
	exitCode := checkCmd.Int("exitCode", 1, "exit code to be used when lint issues are found")
	checkGenerated := checkCmd.Bool("checkGenerated", false, "whether to check generated files")
	checkTests := checkCmd.Bool("checkTests", true, "whether to check test files")
	concurrency := checkCmd.Int("concurrency", 192, "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	goVersion := checkCmd.String("go", "", "select the Go version to target. Leave as string for the latest")
	shorterErrLocation := checkCmd.Bool("shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
	cpuprofile := checkCmd.String("cpuprofile", "", "write CPU profile to the specified file")
	memprofile := checkCmd.String("memprofile", "", "write memory profile to the specified file")

	// Checker-specific parameters
	captLocal_paramsOnly := checkCmd.Bool("@captLocal.paramsOnly", true, "whether to restrict checker to params only")
	commentedOutCode_minLength := checkCmd.Int("@commentedOutCode.minLength", 15, "min length of the comment that triggers a warning")
	elseif_skipBalanced := checkCmd.Bool("@elseif.skipBalanced", true, "whether to skip balanced if-else pairs")
	hugeParam_sizeThreshold := checkCmd.Int("@hugeParam.sizeThreshold", 80, "size in bytes that makes the warning trigger")
	ifElseChain_minThreshold := checkCmd.Int("@ifElseChain.minThreshold", 2, "min number of if-else blocks that makes the warning trigger")
